def _associate_chunks_to_workers(
    num_workers: int, worker_env: _WorkerEnv, chunks_replica: List[int], intervals_replica: List[Any]
) -> Any:

    assigned_chunks = {i: [] for i in range(worker_env.world_size)}
    assigned_intervals = {i: [] for i in range(worker_env.world_size)}

    for i, chunk in enumerate(chunks_replica):
        worker_index = i % worker_env.world_size
        assigned_chunks[worker_index].append(chunk)
        assigned_intervals[worker_index].append(intervals_replica[i])

    return assigned_chunks, assigned_intervals
```

