import os

@contextmanager
def optimize_dns_context(enable: bool) -> Any:
    original_value = os.environ.get('DNS_OPTIMIZATION', 'disabled')
    if enable:
        os.environ['DNS_OPTIMIZATION'] = 'enabled'
    else:
        os.environ['DNS_OPTIMIZATION'] = 'disabled'
    try:
        yield
    finally:
        os.environ['DNS_OPTIMIZATION'] = original_value
