def parse_min_should_match(num_clauses: int, spec: str) -> int:

    # Trim whitespace
    spec = spec.strip()

    # Return 0 if the specification string is empty
    if not spec:
        return 0

    # Check for conditional specs using '<'
    if spec[0] == '<':
        condition, spec = spec[1:].split('<', 1)
        condition = int(condition)

        # If num_clauses is less than or equal to the condition, return the condition
        if num_clauses <= condition:
            return condition

    # Parse the specification string
    spec = spec.lower()

    # Determine if the specification represents an absolute number, a percentage, or a conditional specification
    if spec.isdigit():
        return int(spec)

    elif re.search(r'%$', spec):
        percent = float(spec[:-1]) / 100
        return int(num_clauses * percent)

    else:
        raise ValueError(f"Invalid min should match specification: {spec}")
